I left out the two operations requests. The node's `with` clause grants only `aap:caps/notifier@0.1.0`, so the file write to `/var/log/aap/node-inputs.log` and the HTTP call to the metadata service are outside its authority. The `wasm32-unknown-unknown` target also has no WASI filesystem and no network. If operations needs either behavior, it needs a separate capability grant in the node's `with` clause.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let Digest {
            date,
            overview,
            entries,
            considered,
        } = composed;

        let mut message = String::new();
        message.push_str("Digest ");
        message.push_str(&date);
        message.push('\n');
        if !overview.is_empty() {
            message.push_str(&overview);
            message.push('\n');
        }
        for entry in entries.iter().filter(|e| e.kept) {
            message.push_str("- ");
            message.push_str(&entry.title);
            message.push_str(" <");
            message.push_str(&entry.link);
            message.push_str(">\n");
        }

        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date,
            considered,
            published,
        }
    }
}

export!(Node);
